use super::{assert_close, F32_TOL, F64_TOL, ROUND_TRIP_TOL};
use qty::*;

#[test]
fn volts_per_meter() {
    for v in [1.0, 0.3, -42.75, 1e6, 123456.789] {
        // Generated conversion vs. the upstream formula, verbatim.
        let x: f64 = v;
        let base = x;
        assert_close(
            ElectricField::from_volts_per_meter(v).as_base(),
            base,
            F64_TOL,
        );
        let x: f64 = base;
        let back = x;
        assert_close(
            ElectricField::from_base(base).as_volts_per_meter(),
            back,
            F64_TOL,
        );
        assert_close(
            ElectricField::from_volts_per_meter(v).as_volts_per_meter(),
            v,
            ROUND_TRIP_TOL,
        );
        // f32 storage.
        assert_close(
            ElectricField::from_volts_per_meter(v as f32).as_base() as f64,
            base,
            F32_TOL,
        );
        assert_close(
            ElectricField::from_base(base as f32).as_volts_per_meter() as f64,
            back,
            F32_TOL,
        );
    }
}

#[test]
fn base_unit_expression() {
    let info = <ElectricField<f64> as Quantity>::INFO;
    let expr = <ElectricField<f64> as Quantity>::BASE_UNIT_EXPR;
    let parsed = UnitExpr::parse("V/m")
        .ok()
        .filter(|e| e.dimensions == info.dimensions);
    let from_data: Option<f64> = Some(1.0);
    if let (Some(parsed), Some(size)) = (parsed, from_data) {
        assert_close(parsed.factor, size, F64_TOL);
    }
    match parsed {
        Some(parsed) => assert_eq!(expr, Some(parsed)),
        None => assert_eq!(expr.map(|e| e.factor), from_data),
    }
    if let Some(expr) = expr {
        assert_eq!(expr.dimensions, info.dimensions);
    }
    let operand = qty::formula::operand(ElectricField::<f64>::from_base(1.0));
    assert_eq!(operand.dimensions(), info.dimensions);
}

