#[test]
fn new_and_convert_to_match_named_methods() {
    let v = 1234.5;
    assert_eq!(
        ElectricField::new(v, ElectricFieldUnit::VoltPerMeter),
        ElectricField::from_volts_per_meter(v)
    );
    assert_eq!(
        ElectricField::from_base(v).convert_to(ElectricFieldUnit::VoltPerMeter),
        ElectricField::from_base(v).as_volts_per_meter()
    );
}

#[test]
fn const_new_matches_new() {
    const AT_COMPILE_TIME: [ElectricField; 1] = [ElectricField::const_new(
        1234.5,
        ElectricFieldUnit::VoltPerMeter,
    )];
    for (q, &unit) in AT_COMPILE_TIME.iter().zip(ElectricFieldUnit::ALL) {
        assert_eq!(
            q.as_base().to_bits(),
            ElectricField::new(1234.5_f64, unit).as_base().to_bits(),
            "{unit:?}"
        );
    }
    for v in [0.0, -0.0, 1e-300, -2.5, 3.0e8, f64::MAX] {
        for &unit in ElectricFieldUnit::ALL {
            assert_eq!(
                ElectricField::const_new(v, unit).as_base().to_bits(),
                ElectricField::<f64>::new(v, unit).as_base().to_bits()
            );
        }
    }
}

#[test]
fn in_unit_and_auto_unit_round_trip() {
    for v in [1e-9, 0.5, 1.0, 1234.5, 1e7, -3e4] {
        let q = ElectricField::from_base(v);
        let auto = q.auto_unit();
        assert_close(
            ElectricField::new(auto.value, auto.unit).as_base(),
            v,
            F64_TOL,
        );
        for &unit in ElectricFieldUnit::ALL {
            let shown = q.in_unit(unit);
            assert_eq!((shown.value, shown.unit), (q.convert_to(unit), unit));
        }
    }
    assert_eq!(
        ElectricField::from_base(0.0).auto_unit().unit,
        ElectricFieldUnit::VoltPerMeter
    );
}

#[test]
fn parse_every_abbreviation() {
    assert_eq!(
        "V/m".parse::<ElectricFieldUnit>(),
        Ok(ElectricFieldUnit::VoltPerMeter)
    );
    assert_eq!(
        format!("2.5 {}", "V/m").parse::<ElectricField>(),
        Ok(ElectricField::new(2.5, ElectricFieldUnit::VoltPerMeter))
    );
    assert_eq!(
        "1 not-a-unit".parse::<ElectricField>(),
        Err(ParseError::UnknownUnit)
    );
}

